def extostr(cls, e, max_level=30, max_path_level=5):
    parts = []
    exc = e
    level = 0
    while exc is not None and level < max_level:
        parts.append(f"{type(exc).__name__}: {exc}")
        tb = exc.__traceback__
        stack = traceback.extract_tb(tb)
        if stack:
            parts.append("Stack trace (most recent call last):")
            for frame in stack[-max_level:]:
                filename = frame.filename
                # shorten path
                parts.append(f"  File \"{filename}\", line {frame.lineno}, in {frame.name}")
                parts.append(f"    {frame.line}" if frame.line else "")
        if exc.__cause__:
