    # Turn commands into a list suitable for subprocess.run
    if isinstance(commands, (list, tuple)):
        cmd_list = list(commands)
    elif isinstance(commands, str):
        # Assume a single string command (no shell)
        cmd_list = [commands]
    else:
        raise TypeError(f"commands must be str, list or tuple, got {type(commands).__name__}")

    # Append arguments if they are provided
    if args is not None:
        if isinstance(args, (list, tuple)):
            cmd_list += list(args)
        elif isinstance(args, str):
            cmd_list.append(args)
        else:
            raise TypeError(f"args must be str, list or tuple, got {type(args).__name__}")

    if verbose:
        print(f"Running command: {' '.join(cmd_list)}")
        if cwd:
            print(f"  CWD: {cwd}")

    # Execute the command
    result = subprocess.run(
        cmd_list,
        cwd=cwd,
        env=env,
        capture_output=True,
        text=True,
        check=False
    )

    stdout = result.stdout
    stderr = '' if hide_stderr else result.stderr
    returncode = result.returncode

    if verbose:
        print(f"Return code: {returncode}")
        if not hide_stderr:
            print(f"stderr:\n{stderr}")

    return stdout, returncode, stderr

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0
    # Walk through the root directory and validate each file
    for dirpath, dirnames, filenames in os.walk(self.root):
        for name in filenames:
            num_objects += 1
            file_path = os.path.join(dirpath, name)
            valid = True
            if validate_objects:
                try:
                    # Consider a file valid if it's non-empty
                    if os.path.getsize(file_path) == 0:
                        valid = False
                except OSError:
                    valid = False
            if check_digests and valid:
                # Look for an optional .digest file containing SHA-256 hash
                digest_path = file_path + ".digest"
                if os.path.exists(digest_path):
                    try:
                        with open(digest_path, "rb") as df:
                            expected = df.read().strip()
                        with open(file_path, "rb") as f:
                            data = f.read()
                        actual = hashlib.sha256(data).hexdigest().encode()
                        if actual != expected:
                            valid = False
                    except Exception:
                        valid = False
            if valid:
                good_objects += 1
            elif show_warnings:
