def process_text_links(text):
    import re
    # Add target and rel attributes to existing anchor tags if missing
    def add_anchor_attrs(match):
        tag = match.group(0)
        # Ensure only one set of attributes for each
        if 'target=' not in tag and 'rel=' not in tag:
            tag = tag.replace('<a ', '<a target="_blank" rel="noopener noreferrer" ', 1)
        return tag
    text = re.sub(r'<a\s+[^>]*>', add_anchor_attrs, text)

    # Linkify plain URLs in the text
    url_pattern = re.compile(r'(?P<url>\b(?:https?|ftp)://[^\s<]+)', re.IGNORECASE)

    def replace_url(match):
        url = match.group('url')
        return f'<a href="{url}" target="_blank" rel="noopener noreferrer">{url}</a>'

    return url_pattern.sub(replace_url, text)

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    try:
        # Dynamically import urllib.request to avoid top-level import statements
        urllib_req = __import__('urllib.request')
        req = urllib_req.Request(url, method='HEAD')
        with urllib_req.urlopen(req) as response:
            # getheader is available in older Python versions; fall back to get_content_type
            header = response.headers.get('Content-Type')
            if header:
                return header.split(';', 1)[0].strip()
            else:
                # Fallback to Message object
                info = response.info()
                return info.get_content_type()
    except Exception:
        return None

